	(1316, 'f1665952-4852-455a-9f99-16519ddb83c1', '{"name":"Client Verification Form","description":"Records verification exercise: indication for client verification, verification attempts/steps and client discontinuation. Extracted from the Client Tracking and Discontinuation Form (HIV Tracking Register, form 13).","version":"1.0","published":true,"retired":false,"processor":"EncounterFormProcessor","encounter":"Client Tracking and Termination","referencedForms":[],"uuid":"20e5ef7c-44c3-46cb-aec7-9342096d806e","encounterType":"ba6fb85e-8dc3-43e3-a269-59842cd2d364","pages":[{"label":"Client Verification","sections":[{"label":"Client Verification","isExpanded":"true","questions":[{"label":"Is Client verified","type":"obs","id":"isClientVerified","required":true,"questionOptions":{"concept":"ed586055-dedd-42d3-b87b-2a06715459bd","rendering":"select","answers":[{"concept":"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","label":"Yes"},{"concept":"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","label":"No"}]}},{"label":"Indication for Client Verification (you can select multiple triggers)","type":"obs","id":"indicationsForClientVerification","questionOptions":{"concept":"c42db1b9-46fd-45ea-ae89-f4c30a01be57","rendering":"checkbox","answers":[{"concept":"3bcb19cc-f56a-4b32-ba7e-d1b5bf215371","label":"No initial fingerprint was captured"},{"concept":"4586a817-9491-4f86-8094-fc19b17c0b45","label":"Duplicated demographic and clinical variables"},{"concept":"be100699-ca67-42ed-a196-ff3096ce8522","label":"Last clinical visit is over 15 months prior"},{"concept":"83d5f678-dc44-4e9b-85fa-760a1192b42a","label":"Same sex, DOB and ART start date"},{"concept":"7843063f-7e97-4de1-9968-c18fedfaebd5","label":"Incomplete visit data on the care card or pharmacy forms or EMR"},{"concept":"0875ba7c-bfe7-4d2b-9655-a795a3c5632e","label":"Batched ARV pickup dates"},{"concept":"36e53b0a-144f-4098-a5d8-19ec8de5b770","label":"Records of repeated clinical encounters, with no fingerprint recapture"},{"concept":"f93143cb-3ced-44ef-b64d-e5f3c1ff78fa","label":"Long intervals between ARV pick-ups (pick-ups more than one year apart in the same facility)"},{"concept":"28ed9571-a41f-44d4-b420-2bd8cef3059c","label":"Records with same services (e.g. ART start date and at least 3 consecutive last ART pickup dates, VL result etc.)"},{"concept":"159d4316-948b-4d84-8d42-4801d9815475","label":"Consistently had drug pickup by proxy without viral load sample collection for two quarters"}]},"hide":{"hideWhenExpression":"isClientVerified !== \'1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\'"}},{"label":"Others (Specify)","type":"obs","id":"otherIndicationForClientVerification","questionOptions":{"concept":"2e76fea9-f6e2-4fa1-844e-78ebe53223de","rendering":"text"},"hide":{"hideWhenExpression":"isClientVerified !== \'1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\'"}}]},{"label":"Verification Attempts and Steps","isExpanded":"true","questions":[{"label":"Verification Attempt","type":"obsGroup","id":"verificationAttemptAndStep","questionOptions":{"concept":"d6bd121e-19d2-49cc-b3a2-9114724d3787","rendering":"repeating","repeatOptions":{"limit":"5"}},"questions":[{"label":"Date of Client Tracking","type":"obs","id":"dateOfClientTracking","questionOptions":{"concept":"f996800e-eba9-4f8d-9a54-1c878279d5d2","rendering":"date"},"validators":[{"type":"date","allowFutureDates":false}]},{"label":"Verification Attempts (you can select multiple)","type":"obs","id":"verificationAttempts","questionOptions":{"concept":"c6f5016d-6e55-46d6-84e8-3d37918abd23","rendering":"checkbox","answers":[{"concept":"78211f44-c9e2-4507-96e5-f6d46153685b","label":"Physical document audited - folder / register review"},{"concept":"2b317c32-906e-442d-8028-2bb4213c3d8e","label":"Client contacted"},{"concept":"dce41e86-3533-4f31-b3a4-378edccd255c","label":"1st Biometric capture"},{"concept":"eb5739c6-b747-4301-9976-cde523cc1eb5","label":"Facility visit"},{"concept":"5a5f62d4-9688-41a3-bca8-e0f6559ae393","label":"Biometric recapture"}]}},{"label":"Verification Status","type":"obs","id":"verificationStatus","questionOptions":{"concept":"08728221-0130-4016-9b73-dbfd45a1ffbe","rendering":"select","answers":[{"concept":"a43118e8-7cc3-42ba-8a28-8c7528bd6f02","label":"Verification ongoing"},{"concept":"9b052f1b-0609-4071-ab3b-cc444bd071ef","label":"Records Discontinued & Archived"},{"concept":"199ec5ab-233e-44e9-99ce-5631a546321e","label":"Record verified"}]},"validators":[{"type":"js_expression","failsWhenExpression":"!isEmpty(dateOfClientTracking) && isEmpty(myValue)","message":"Verification status is required once a date of client tracking is entered"}]},{"label":"Outcome","type":"obs","id":"verificationOutcome","questionOptions":{"concept":"9a671e64-5ebc-412f-9d46-0231d337e8aa","rendering":"select","answers":[{"concept":"687ae195-e9a6-46f5-9739-57b465c476a4","label":"Valid"},{"concept":"163611AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","label":"Invalid"}]}},{"label":"Comments (provide reason for records discontinuation)","type":"obs","id":"verificationComments","questionOptions":{"concept":"71c6a4eb-7860-4b7e-90ea-c45aadd26c82","rendering":"textarea"}}]}]}]},{"label":"Client Discontinuation","sections":[{"label":"Client Discontinuation","isExpanded":"true","questions":[{"label":"Patient Care in Facility Discontinued:","type":"obs","id":"careInFacilityDiscontinued","questionOptions":{"concept":"4b24ffc8-dce0-43c9-9663-fc03919c766c","rendering":"select","answers":[{"concept":"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","label":"No"},{"concept":"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","label":"Yes"}]}},{"label":"Date of Discontinuation","type":"obs","id":"date_of_termination","questionOptions":{"concept":"38e672ba-2fac-4907-8740-9cc1ca0b0a71","rendering":"date"},"hide":{"hideWhenExpression":"careInFacilityDiscontinued !== \'1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\'"},"validators":[{"type":"date","allowFutureDates":false}]},{"label":"Reason for Discontinuation","type":"obs","id":"reasonForDiscontinuation","questionOptions":{"concept":"96cf7